python3 -c 'import json,subprocess,pathlib
names=["gdm","gts9-adbd","gts9-usb-acm","gts9-usb-typec-lifecycle","ssh"]
out={"boot_id":pathlib.Path("/proc/sys/kernel/random/boot_id").read_text().strip(),"services":{}}
for n in names:
 p=subprocess.run(["systemctl","show",n,"--property=LoadState,ActiveState,SubState,Result"],capture_output=True,text=True,timeout=5)
 out["services"][n]={"returncode":p.returncode,"stdout":p.stdout,"stderr":p.stderr}
print(json.dumps(out,indent=2))'
